def sha(b): return hashlib.sha256(b).hexdigest()
def fail(m): raise SystemExit("FAIL: "+m)
def apply(root):
    root=Path(root)
    for rel,spec in FILES.items():
        p=root/rel
        if not p.is_file(): fail("missing exact 26535 base file: "+rel)
        old=p.read_bytes()
        if sha(old)!=spec["base"]: fail("base hash drift for "+rel+" got="+sha(old)+" expected="+spec["base"])
        data=zlib.decompress(base64.b85decode(spec["data"].encode()))
        if sha(data)!=spec["cand"]: fail("embedded candidate payload corrupt for "+rel)
        p.write_bytes(data)
        if sha(p.read_bytes())!=spec["cand"]: fail("write verification failed for "+rel)
    print("PASS: 26536 exact six-file transform applied")
def self_test():
    if len(FILES)!=6 or len(set(FILES))!=6: fail("runtime file list drift")
    for rel,spec in FILES.items():
        data=zlib.decompress(base64.b85decode(spec["data"].encode()))
        if sha(data)!=spec["cand"]: fail("payload self-test failed "+rel)
        if spec["base"]==spec["cand"]: fail("non-changing payload "+rel)
    print("PASS: 26536 embedded exact candidate payloads verified 6/6")
def main():
    ap=argparse.ArgumentParser();ap.add_argument("root",nargs="?");ap.add_argument("--self-test",action="store_true");a=ap.parse_args()
    if a.self_test: self_test(); return
    if not a.root: fail("root required")
    apply(a.root)
if __name__=="__main__": main()
